from pathlib import Path
import json,hashlib,numpy as np
items=[('M2-2','b80-upright-current-state-plans'),('M2-2','b81-measured-liftoff-gate'),('M2-2','b82-bounded-foot-unload'),('M2-4','b39-upright-current-state-plans'),('M2-4','b40-measured-liftoff-gate'),('M2-4','b41-ankle-reserve-and-unload'),('M2-4','b42-bounded-balance-integral'),('M2-4','b43-adaptive-body-preload'),('M2-2','b83-lower-stance-grip-relief'),('M2-2','b84-shared-load-force-regulation')]
items += [('M2-2', 'b85-clear-policy-handoff'), ('M2-2', 'b86-high-upright-shared-stance'), ('M2-2', 'b87-high-full-body-policy'), ('M2-2', 'b88-cargo-arrival-balance-stop'), ('M2-2', 'b89-thirty-centimeter-carry'), ('M2-4', 'b44-upright-policy-handoff'), ('M2-4', 'b45-high-full-body-policy'), ('M2-4', 'b46-cargo-arrival-balance-stop')]
out=[]
for case,name in items:
 p=Path('m2_extension')/case/'attempts'/name/'run';raw=(p/'trajectory.json').read_bytes();rows=json.loads(raw);result=json.loads((p/'result.json').read_text());selfreview=json.loads((p/'self-contact-review.json').read_text());gait=[r for r in rows if 'com_error_m'in r.get('motion_diagnostics',{})];stance=[r for r in rows if r['phase']=='verify_planned_supported_stance'];speed=[float(np.linalg.norm(r['objects']['cargo']['vel']))for r in stance];last=gait[-1].get('motion_diagnostics',{})if gait else{};dwell=longest=0.
 for r in stance:
  dwell=dwell+.02 if np.linalg.norm(r['objects']['cargo']['vel'])<.03 else 0.;longest=max(longest,dwell)
 load=last.get('foot_vertical_load_N',[])
 out.append(dict(case=case,attempt=name,trajectory_sha256=hashlib.sha256(raw).hexdigest(),terminal_time_s=result['seconds'],terminal_phase=rows[-1]['phase'],reason=result['reason'],full_task_success=result['task_success'],torso_arm_peak_N=selfreview['peak_force_N'],max_gait_com_error_m=max((float(np.linalg.norm(r['motion_diagnostics']['com_error_m']))for r in gait),default=None),terminal_com_error_m=last.get('com_error_m'),terminal_foot_vertical_load_N=load,terminal_smaller_foot_load_fraction=min(load)/sum(load)if load and sum(load)>0 else None,max_liftoff_wait_s=max((r.get('motion_diagnostics',{}).get('liftoff_wait_s',0.)for r in rows)),max_extra_unload_lift_m=max((max(r.get('motion_diagnostics',{}).get('unload_foot_lift_m',[0]))for r in rows)),ever_entered_swing=any(r['phase']=='quasistatic_swing'for r in rows),stance_cargo_speed_m_s=dict(min=min(speed),max=max(speed),mean=float(np.mean(speed)),longest_below_30mm_s_s=longest)if speed else None))
report=dict(schema='m2-measured-gait-diagnosis/1',scope='Recorded50Hz control diagnostics plus independent200Hz torso-contact audit. Neither sampled kinematics nor stage milestones establish complete delivery.',source_script_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),attempts=out,formal_admission=False)
Path('infra/planning/m2-extension/acceptance/measured-gait-diagnosis.json').write_text(json.dumps(report,indent=2)+'\n');print([{k:r[k]for k in ('case','attempt','reason','torso_arm_peak_N','terminal_smaller_foot_load_fraction')}for r in out])
